{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_7a32409da6bac753bccff672", "claim_ids": ["claim_836c9fa48dd797ea55eecf40", "claim_a29024f866fedd6f2f73598f"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_836c9fa48dd797ea55eecf40", "quote": "8708100050—Bumpers and parts, nesoi, of headings 8701 to 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Bumpers and parts, nesoi", "hts_code": "8708100050"}}, {"claim_id": "claim_a29024f866fedd6f2f73598f", "quote": "- 8708100050 Bumpers and Parts", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"chapter_99_code": "8708100050"}}]}, {"pair_id": "conflict_64c99bf6f1a3f4e779f218ce", "claim_ids": ["claim_836c9fa48dd797ea55eecf40", "claim_b4d47ea565c059252e6b9956"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_836c9fa48dd797ea55eecf40", "quote": "8708100050—Bumpers and parts, nesoi, of headings 8701 to 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Bumpers and parts, nesoi", "hts_code": "8708100050"}}, {"claim_id": "claim_b4d47ea565c059252e6b9956", "quote": "8708100050—BUMPERS AND PARTS, NESOI, OF HEADINGS 8701 TO 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "BUMPERS AND PARTS, NESOI", "hts_code": "8708100050"}}]}, {"pair_id": "conflict_d44eaccec8c3c0cdb6b52586", "claim_ids": ["claim_a29024f866fedd6f2f73598f", "claim_b4d47ea565c059252e6b9956"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_a29024f866fedd6f2f73598f", "quote": "- 8708100050 Bumpers and Parts", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"chapter_99_code": "8708100050"}}, {"claim_id": "claim_b4d47ea565c059252e6b9956", "quote": "8708100050—BUMPERS AND PARTS, NESOI, OF HEADINGS 8701 TO 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "BUMPERS AND PARTS, NESOI", "hts_code": "8708100050"}}]}, {"pair_id": "conflict_38758f58e2d642580e3ab374", "claim_ids": ["claim_3d3ed88bb5e05f3e08bc9072", "claim_75139dee8e4d31964346893a"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_3d3ed88bb5e05f3e08bc9072", "quote": "The purpose of this message is to provide guidance on the 25 percent duty on imports of certain automobile parts from all countries effective 12:01 a.m. ET on May 3, 2025.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Presidential Proclamation 10908", "duty_rate": "25 percent", "effective_date": "May 3, 2025", "reported_policy_status": "GUIDANCE: Import Duties on Certain Automobile Parts"}}, {"claim_id": "claim_75139dee8e4d31964346893a", "quote": "On March 26, 2025, the President issued Proclamation 10908 on Adjusting Imports of Automobiles and Automobile Parts into the United States, imposing a 25 percent ad valorem tariff on parts of passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks from all countries, under Section 232 of the Trade Expansion Act of 1962, as amended (19 U.S.C. 1862) (Section 232), effective May 3, 2025.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "Section 232 of the Trade Expansion Act of 1962", "affected_product": "parts of passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks", "duty_rate": "25 percent ad valorem tariff"}}]}, {"pair_id": "conflict_5187623c71d7625af5c66371", "claim_ids": ["claim_8a7c3f5dc982515bce372a62", "claim_b144dbb007906594bddebbce"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_8a7c3f5dc982515bce372a62", "quote": "CBP is proposing to reclassify bumper energy absorbers, bumper extensions, and bumper reinforcements as bumper parts under HTSUS 8708.10.60 (2.5 percent duty) rather than as other motor vehicle parts under HTSUS 8708.29.5060 (2.5 percent duty).", "url": "https://www.strtrade.com/trade-news-resources/str-trade-report/trade-report/september/classification-changes-proposed-for-car-cleaner-bumper-parts-playmats", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "tariff_program": "HTSUS 8708.10.60", "duty_rate": "2.5 percent", "reported_policy_status": "proposed revocations or modifications"}}, {"claim_id": "claim_b144dbb007906594bddebbce", "quote": "CBP explains that these items absorb impact and provide rigidity and protection to the bumper, functions that are integral to the function of the bumper, and are thus properly classified as parts.", "url": "https://www.strtrade.com/trade-news-resources/str-trade-report/trade-report/september/classification-changes-proposed-for-car-cleaner-bumper-parts-playmats", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_92e6878f962691791d524aab", "claim_ids": ["claim_72bc31839268f0fea88a877e", "claim_81f8e9c2ba4bd1a79cb9ab71"], "query_ids": ["q_334"], "claims": [{"claim_id": "claim_72bc31839268f0fea88a877e", "quote": "The USMCA origin rule matters for companies that have shifted wire harness production to Mexico. If your Mexican facility sources Chinese wire but performs all cutting, stripping, crimping, and assembly in Mexico, the finished harness qualifies as Mexican-origin — eliminating both base duty and Section 301.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "USMCA", "country_of_origin": "Mexican-origin"}}, {"claim_id": "claim_81f8e9c2ba4bd1a79cb9ab71", "quote": "facility sources Chinese wire but performs all cutting, stripping, crimping, and assembly in Mexico, the finished harness qualifies as Mexican-origin — eliminating both base duty and Section 301.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Mexican-origin", "duty_rate": "eliminating both base duty and Section 301"}}]}, {"pair_id": "conflict_5c6c452e401b2dabf805e04f", "claim_ids": ["claim_bd1b99e6415116ee613e4e6f", "claim_c921d8e53d0100db20e66c9f"], "query_ids": ["q_334"], "claims": [{"claim_id": "claim_bd1b99e6415116ee613e4e6f", "quote": "Section 301 tariffs turned cable assembly sourcing into a classification exercise. We have customers who moved connector crimping to Vietnam while keeping wire cutting in China — the substantial transformation shifted the country of origin and dropped effective duty from 28% to 2.6%. The HS code stayed the same; only the origin changed.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Vietnam", "exporting_country": "China", "duty_rate": "2.6%"}}, {"claim_id": "claim_c921d8e53d0100db20e66c9f", "quote": "If your Mexican facility sources Chinese wire but performs all cutting, stripping, crimping, and assembly in Mexico, the finished harness qualifies as Mexican-origin — eliminating both base duty and Section 301.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Mexican-origin"}}]}, {"pair_id": "conflict_4c7d653adb4bad99cc830fec", "claim_ids": ["claim_024a957bf8a5df6a30d3318b", "claim_93c866600a63fd6fcad82ab4"], "query_ids": ["q_335"], "claims": [{"claim_id": "claim_024a957bf8a5df6a30d3318b", "quote": "For automotive wire harnesses from China under HTS 8544.30.0000, the base MFN duty is 5% plus 25% Section 301, totaling 30% of customs value.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "30%"}}, {"claim_id": "claim_93c866600a63fd6fcad82ab4", "quote": "For HTS 8544.30.0000 (vehicle harnesses), the base 5% plus 25% Section 301 brings the effective rate to 30%. HTS 8544.42.2000 (copper conductors with connectors) carries 2.6% base plus 25% Section 301, totaling 27.6%.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "vehicle harnesses", "duty_rate": "effective rate to 30%"}}]}, {"pair_id": "conflict_a20f3710acffa2fe765d2c64", "claim_ids": ["claim_1196aa501581ccee55abf988", "claim_93c866600a63fd6fcad82ab4"], "query_ids": ["q_335"], "claims": [{"claim_id": "claim_1196aa501581ccee55abf988", "quote": "We have customers who moved connector crimping to Vietnam while keeping wire cutting in China — the substantial transformation shifted the country of origin and dropped effective duty from 28% to 2.6%. The HS code stayed the same; only the origin changed.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "China", "duty_rate": "dropped effective duty from 28% to 2.6%"}}, {"claim_id": "claim_93c866600a63fd6fcad82ab4", "quote": "For HTS 8544.30.0000 (vehicle harnesses), the base 5% plus 25% Section 301 brings the effective rate to 30%. HTS 8544.42.2000 (copper conductors with connectors) carries 2.6% base plus 25% Section 301, totaling 27.6%.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "vehicle harnesses", "duty_rate": "effective rate to 30%"}}]}, {"pair_id": "conflict_437d9dc8440d85e97b0497aa", "claim_ids": ["claim_468645ffbe7c5439ff1dd948", "claim_c2d90fe12c14affdbbe4e244"], "query_ids": ["q_335"], "claims": [{"claim_id": "claim_468645ffbe7c5439ff1dd948", "quote": "If the cable has any termination — crimped terminals, molded plugs, board-level headers — it classifies under 8544.42 (fitted with connectors). HS 8544.49 is for unterminated cable only.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_c2d90fe12c14affdbbe4e244", "quote": "A procurement manager at a medical device company classified 2,000 shielded cable assemblies under HS 8544.49 instead of 8544.42 — missing the 'fitted with connectors' distinction. CBP held the shipment for three weeks and assessed $8,400 in penalty duties.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "medical device company", "duty_rate": "$8,400 in penalty duties"}}]}]}

